lines = ['<!DOCTYPE html>', '<html lang="vi">', '<head>', '    <meta charset="UTF-8">', '    <meta name="viewport" content="width=device-width, initial-scale=1.0">', '    <title>Payment Fraud Detection & Prevention System</title>', '    <script src="https://cdn.tailwindcss.com"></script>', '    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>', '    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">', '    <style>', '        body { font-family: system-ui, -apple-system, sans-serif; background-color: #0f172a; color: #f8fafc; }', '        .tab-btn.active { border-bottom: 3px solid #3b82f6; color: #60a5fa; font-weight: 600; }', '        .glass-card { background: rgba(30, 41, 59, 0.7); backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.08); }', '        .risk-badge-LOW { background-color: rgba(34, 197, 94, 0.2); color: #4ade80; border: 1px solid rgba(34, 197, 94, 0.3); }', '        .risk-badge-MEDIUM { background-color: rgba(234, 179, 8, 0.2); color: #facc15; border: 1px solid rgba(234, 179, 8, 0.3); }', '        .risk-badge-HIGH { background-color: rgba(249, 115, 22, 0.2); color: #fb923c; border: 1px solid rgba(249, 115, 22, 0.3); }', '        .risk-badge-CRITICAL { background-color: rgba(239, 68, 68, 0.2); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.3); }', '        .decision-APPROVE, .decision-APPROVED { background-color: #166534; color: #86efac; }', '        .decision-REVIEW { background-color: #854d0e; color: #fef08a; }', '        .decision-BLOCK, .decision-BLOCKED { background-color: #991b1b; color: #fca5a5; }', '    </style>', '</head>', '<body class="min-h-screen flex flex-col">', '    <header class="glass-card sticky top-0 z-50 px-6 py-4 flex flex-wrap justify-between items-center border-b border-slate-700/50">', '        <div class="flex items-center space-x-3">', '            <div class="bg-blue-600/30 p-2.5 rounded-xl border border-blue-500/30 text-blue-400">', '                <i class="fa-solid fa-shield-halved text-2xl"></i>', '            </div>', '            <div>', '                <h1 class="text-xl font-bold text-white tracking-wide">Fraud Guard AI</h1>', '                <p class="text-xs text-slate-400">Payment Fraud Detection Engine (FastAPI)</p>', '            </div>', '        </div>', '        <nav class="flex space-x-1 sm:space-x-4 mt-3 sm:mt-0 text-sm overflow-x-auto">', '            <button onclick="switchTab(\'dashboard\')" id="tab-dashboard" class="tab-btn active px-3 py-2 text-slate-300 hover:text-white transition">', '                <i class="fa-solid fa-chart-line mr-1.5"></i> Dashboard', '            </button>', '            <button onclick="switchTab(\'simulation\')" id="tab-simulation" class="tab-btn px-3 py-2 text-slate-300 hover:text-white transition">', '                <i class="fa-solid fa-bolt mr-1.5"></i> Live Simulator', '            </button>', '            <button onclick="switchTab(\'transactions\')" id="tab-transactions" class="tab-btn px-3 py-2 text-slate-300 hover:text-white transition">', '                <i class="fa-solid fa-receipt mr-1.5"></i> Transactions', '            </button>', '            <button onclick="switchTab(\'store\')" id="tab-store" class="tab-btn px-3 py-2 text-slate-300 hover:text-white transition">', '                <i class="fa-solid fa-cart-shopping mr-1.5"></i> Storefront', '            </button>', '            <button onclick="switchTab(\'rules\')" id="tab-rules" class="tab-btn px-3 py-2 text-slate-300 hover:text-white transition">', '                <i class="fa-solid fa-sliders mr-1.5"></i> Rules', '            </button>', '            <button onclick="switchTab(\'evaluation\')" id="tab-evaluation" class="tab-btn px-3 py-2 text-slate-300 hover:text-white transition">', '                <i class="fa-solid fa-bullseye mr-1.5"></i> Benchmark', '            </button>', '        </nav>', '    </header>']
